import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BSaF8iZ6.js";const u=JSON.parse('{"title":"Admin Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/admin-quick-start.md","filePath":"getting-started/admin-quick-start.md","lastUpdated":1789411447000}'),s={name:"getting-started/admin-quick-start.md"};function l(n,e,i,h,d,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="admin-quick-start" tabindex="-1">Admin Quick Start <a class="header-anchor" href="#admin-quick-start" aria-label="Permalink to &quot;Admin Quick Start&quot;">​</a></h1><div class="page-roles"><span class="role role--admin">Admin</span></div><p>This page walks you through setting up the marketplace and the work that follows, in the order you&#39;ll usually need it. Each step links to the page with the details.</p><h2 id="set-up-the-marketplace" tabindex="-1">Set up the marketplace <a class="header-anchor" href="#set-up-the-marketplace" aria-label="Permalink to &quot;Set up the marketplace&quot;">​</a></h2><h3 id="_1-turn-it-on-and-set-your-commission" tabindex="-1">1. Turn it on and set your commission <a class="header-anchor" href="#_1-turn-it-on-and-set-your-commission" aria-label="Permalink to &quot;1. Turn it on and set your commission&quot;">​</a></h3><p>Make sure the marketplace is on, and choose the commission your store keeps from each seller sale. See <a href="./../configuration/general">General</a> and <a href="./../payments/commission-management">Commission</a>.</p><h3 id="_2-decide-how-sellers-join" tabindex="-1">2. Decide how sellers join <a class="header-anchor" href="#_2-decide-how-sellers-join" aria-label="Permalink to &quot;2. Decide how sellers join&quot;">​</a></h3><p>Choose whether new sellers wait for your approval, whether their shops are public, and what they can do with orders. See <a href="./../configuration/sellers">Sellers settings</a>.</p><h3 id="_3-decide-how-products-are-added" tabindex="-1">3. Decide how products are added <a class="header-anchor" href="#_3-decide-how-products-are-added" aria-label="Permalink to &quot;3. Decide how products are added&quot;">​</a></h3><p>Choose whether sellers create their own products, sell products from your catalog, or both, and whether you approve each product first. See <a href="./../configuration/products">Products settings</a>.</p><h3 id="_4-set-up-the-landing-page" tabindex="-1">4. Set up the landing page <a class="header-anchor" href="#_4-set-up-the-landing-page" aria-label="Permalink to &quot;4. Set up the landing page&quot;">​</a></h3><p>Write the page that invites visitors to become sellers, and choose which sellers to feature on it. See <a href="./../configuration/landing-page">Landing Page</a> and <a href="./../configuration/featured-sellers">Featured Sellers</a>.</p><h3 id="_5-add-what-your-marketplace-needs" tabindex="-1">5. Add what your marketplace needs <a class="header-anchor" href="#_5-add-what-your-marketplace-needs" aria-label="Permalink to &quot;5. Add what your marketplace needs&quot;">​</a></h3><ul><li><strong>Subscription plans</strong> to charge sellers. See <a href="./../subscriptions/seller-subscription-management">Plans &amp; Subscriptions</a>.</li><li><strong>Generative AI</strong> for seller listings. See <a href="./../configuration/generative-ai">Generative AI Configuration</a>.</li><li><strong>Reporting</strong> of products and sellers, and account-health thresholds. See <a href="./../configuration/moderation-and-health">Moderation &amp; Health</a>.</li><li><strong>Extra seller fields</strong>, such as a tax number. See <a href="./../sellers/seller-attributes">Seller Attributes</a>.</li></ul><h2 id="run-the-marketplace" tabindex="-1">Run the marketplace <a class="header-anchor" href="#run-the-marketplace" aria-label="Permalink to &quot;Run the marketplace&quot;">​</a></h2><h3 id="approve-sellers" tabindex="-1">Approve sellers <a class="header-anchor" href="#approve-sellers" aria-label="Permalink to &quot;Approve sellers&quot;">​</a></h3><p>Review new sign-ups and approve or disapprove them. See <a href="./../sellers/seller-management">Seller Management</a>.</p><h3 id="approve-products" tabindex="-1">Approve products <a class="header-anchor" href="#approve-products" aria-label="Permalink to &quot;Approve products&quot;">​</a></h3><p>Approve or reject the products sellers submit. See <a href="./../catalog/product-approval">Product Approval</a>.</p><h3 id="follow-orders-and-returns" tabindex="-1">Follow orders and returns <a class="header-anchor" href="#follow-orders-and-returns" aria-label="Permalink to &quot;Follow orders and returns&quot;">​</a></h3><p>See every seller&#39;s part of each order, and handle returns. See <a href="./../orders/order-management">Order Management</a> and <a href="./../orders/return-merchandise-authorization">Returns (RMA)</a>.</p><h3 id="pay-sellers" tabindex="-1">Pay sellers <a class="header-anchor" href="#pay-sellers" aria-label="Permalink to &quot;Pay sellers&quot;">​</a></h3><p>Pay sellers for completed orders when they request it, one at a time or several at once. See <a href="./../payments/payment-management">Payment Requests &amp; Payouts</a>.</p><h3 id="keep-the-marketplace-healthy" tabindex="-1">Keep the marketplace healthy <a class="header-anchor" href="#keep-the-marketplace-healthy" aria-label="Permalink to &quot;Keep the marketplace healthy&quot;">​</a></h3><ul><li>Watch each seller&#39;s cancellations, ratings and flags in <a href="./../sellers/seller-account-health">Account Health</a>.</li><li>Approve reviews in <a href="./../moderation/rating-management">Reviews &amp; Ratings</a>.</li><li>Look into reports in <a href="./../moderation/seller-product-flagging">Seller &amp; Product Flagging</a>.</li><li>Answer sellers in <a href="./../customers/communications">Communications</a>.</li></ul>',25)])])}const m=a(s,[["render",l]]);export{u as __pageData,m as default};
